        return ExitStatus.ERROR_TOO_MANY_REDIRECTS
    except Exception as e:
        return handle_generic_exceptions(e, env, include_traceback)

def handle_system_exceptions(e, env, include_traceback):
    env.stderr.write('\n')
    if isinstance(e, KeyboardInterrupt):
        return handle_interrupt(env, include_traceback, ExitStatus.ERROR_CTRL_C)
    elif isinstance(e, SystemExit):
        return handle_systemexit_exception(e, env, include_traceback)

def handle_interrupt(env, include_traceback, exit_code):
    if include_traceback:
        raise
    return exit_code

def handle_systemexit_exception(e, env, include_traceback):
    if e.code != ExitStatus.SUCCESS:
        env.stderr.write('\n')
        if include_traceback:
