```python
def jsonable_encoder(
    obj,
    include=None,
    exclude=None,
    by_alias=True,
    exclude_unset=False,
    exclude_defaults=False,
    exclude_none=False,
    custom_encoder=None,
    sqlalchemy_safe=True,
):
    custom_encoder = custom_encoder or {}
    obj_type = type(obj)

    # Utilize specific custom encoders if available
    if obj_type in custom_encoder:
        return custom_encoder[obj_type](obj)
    for encoder_type, encoder_instance in custom_encoder.items():
        if isinstance(obj, encoder_type):
            return encoder_instance(obj)

    # Convert include and exclude to sets if they are not None or already a set/dict
    include = set(include) if include and not isinstance(include, (set, dict)) else include
    exclude = set(exclude) if exclude and not isinstance(exclude, (set, dict)) else exclude

    # Handle Pydantic BaseModel
    if isinstance(obj, BaseModel):
        encoder = getattr(obj.__config__, "json_encoders", {})
        encoder.update(custom_encoder)
        obj_dict = obj.dict(include=include, exclude=exclude, by_alias=by_alias, exclude_unset=exclude_unset, exclude_none=exclude_none, exclude_defaults=exclude_defaults)
        return jsonable_encoder(obj_dict["__root__"] if "__root__" in obj_dict else obj_dict, exclude_none=exclude_none, exclude_defaults=exclude_defaults, custom_encoder=encoder, sqlalchemy_safe=sqlalchemy_safe)

    # Handle dataclasses
    if dataclasses.is_dataclass(obj):
        return dataclasses.asdict(obj)

    # Handle Enums, Paths, and Simple Types
    if isinstance(obj, Enum):
        return obj.value
    if isinstance(obj, PurePath):
        return str(obj)
    if isinstance(obj, (str, int, float, type(None))):
        return obj

    # Handle dictionary types
    if isinstance(obj, dict):
        return {
            jsonable_encoder(k, by_alias=by_alias, exclude_unset=exclude_unset, exclude_none=exclude_none, custom_encoder=custom_encoder, sqlalchemy_safe=sqlalchemy_safe): jsonable_encoder(v, by_alias=by_alias, exclude_unset=exclude_unset, exclude_none=exclude_none, custom_encoder=custom_encoder, sqlalchemy_safe=sqlalchemy_safe)
            for k, v in obj.items()
            if (not sqlalchemy_safe or not isinstance(k, str) or not k.startswith("_sa")) and (v is not None or not exclude_none) and k in include or k not in exclude
        }

    # Handle lists and other iterable objects
    if isinstance(obj, (list, set, frozenset, GeneratorType, tuple)):
        return [
            jsonable_encoder(item, include=include, exclude=exclude, by_alias=by_alias, exclude_unset=exclude_unset, exclude_defaults=exclude_defaults, exclude_none=exclude_none, custom_encoder=custom_encoder, sqlalchemy_safe=sqlalchemy_safe)
            for item in obj
        ]

    # Use general encoders for object types, if available
    if obj_type in ENCODERS_BY_TYPE:
        return ENCODERS_BY_TYPE[obj_type](obj)
    for encoder, classes_tuple in encoders_by_class_tuples.items():
        if isinstance(obj, classes_tuple):
            return encoder(obj)

    # Attempt to treat the object as a dictionary, fallback to attributes
    try:
        data = dict(obj)
    except Exception as e:
        try:
            data = vars(obj)
        except Exception as ex:
            raise ValueError([e, ex])
    return jsonable_encoder(data, include=include, exclude=exclude, by_alias=by_alias, exclude_unset=exclude_unset, exclude_defaults=exclude_defaults, exclude_none=exclude_none, custom_encoder=custom_encoder, sqlalchemy_safe=sqlalchemy_safe)
```

