def find_best_app(script_info, module):
    from . import Flask

    # First, try standard attribute names for a Flask application
    for attr_name in ("app", "application"):
        app = getattr(module, attr_name, None)
        if isinstance(app, Flask):
            return app

    # Secondly, handle cases with one or more Flask apps defined directly in module.__dict__
    matches = [v for v in module.__dict__.values() if isinstance(v, Flask)]
    if matches:
        if len(matches) == 1:
            return matches[0]
        raise NoAppException(
            f"Detected multiple Flask applications in module {module.__name__!r}. "
            f"Use 'FLASK_APP={module.__name__}:name' to specify the correct one."
        )

    # Lastly, identify and run factory functions if provided
    for attr_name in ("create_app", "make_app"):
        app_factory = getattr(module, attr_name, None)
        if callable(app_factory):
            try:
                app = call_factory(script_info, app_factory)
                if isinstance(app, Flask):
                    return app
            except TypeError:
                if not _called_with_wrong_args(app_factory):
                    raise
                raise NoAppException(
                    f"Detected factory {attr_name!r} in module {module.__name__!r}, "
                    f"but could not call it without arguments. Use "
                    f"\"FLASK_APP='{module.__name__}:{attr_name}(args)'\" to specify arguments."
                )

    # If no app or valid factory is found
    raise NoAppException(
        f"Failed to find Flask application or factory in module {module.__name__!r}. "
        f"Use 'FLASK_APP={module.__name__}:name' to specify one."
    )
