            locked = self.get_locked(dep)
            if locked is None or not locked.package.is_same_package_as(dep):
                self.search_for_direct_origin_dependency(dep)
    return dependencies

def apply_overrides(self, dependencies, dependency_package):
    overridden_dependencies = self._get_dependencies_with_overrides(dependencies, dependency_package)
    return overridden_dependencies

