    if self.batch_size == "auto":
        return min(200, n_samples)
    if self.batch_size > n_samples:
        warnings.warn(
            "Got `batch_size` less than 1 or larger than sample size. It will be clipped",
            UserWarning,
        )
    return np.clip(self.batch_size, 1, n_samples)

def _post_process_iteration(self, early_stopping, X_val, y_val, accumulated_loss, n_samples):
    self.loss_ = accumulated_loss / n_samples
    self.t_ += n_samples
    self.loss_curve_.append(self.loss_)
    if self.verbose:
        print(f"Iteration {self.n_iter_}, loss = {self.loss_:.8f}")
    self._update_no_improvement_count(early_stopping, X_val, y_val)
    self._optimizer.iteration_ends(self.t_)
    if self._no_improvement_count > self.n_iter_no_change:
        msg = self._construct_stop_message(early_stopping)
        if self._optimizer.trigger_stopping(msg, self.verbose):
            return

def _construct_stop_message(self, early_stopping):
    if early_stopping:
        return f"Validation score did not improve more than tol={self.tol} for {self.n_iter_no_change} consecutive epochs."
    return f"Training loss did not improve more than tol={self.tol} for {self.n_iter_no_change} consecutive epochs."

def _process_batches(self, X, y, sample_idx, activations, deltas, coef_grads, intercept_grads, batch_size, params):
    accumulated_loss = 0.0
    for batch_slice in gen_batches(len(X), batch_size):
        X_batch, y_batch = self._get_batch(X, y, sample_idx, batch_slice)
        activations[0] = X_batch
        batch_loss, coef_grads, intercept_grads = self._backprop(X_batch, y_batch, activations, deltas, coef_grads, intercept_grads)
        accumulated_loss += batch_loss * (batch_slice.stop - batch_slice.start)
        self._optimizer.update_params(params, coef_grads + intercept_grads)
    self.n_iter_ += 1
    return accumulated_loss

def _get_batch(self, X, y, sample_idx, batch_slice):
    if self.shuffle:
        indices = sample_idx[batch_slice]
    else:
        indices = batch_slice
    return _safe_indexing(X, indices), y[indices]
