def _mini_batch_step(X, x_squared_norms, centers, counts, old_center_buffer, compute_squared_diff, distances, random_reassign=False, random_state=None, reassignment_ratio=.01, verbose=False):
    nearest_center, inertia = _labels_inertia(X, x_squared_norms, centers, distances=distances)

    if random_reassign and reassignment_ratio > 0:
        random_state = check_random_state(random_state)
        to_reassign = (counts <= 1) | (counts <= reassignment_ratio * counts.max())
        n_reassigns = min(to_reassign.sum(), X.shape[0])

        if n_reassigns:
            update_distances_for_reassignment(distances)
            new_centers = select_new_centers(distances, n_reassigns, random_state)
            log_reassignment(n_reassigns, verbose)
            reassign_centers(X, new_centers, to_reassign, centers)

    if sp.issparse(X):
        return inertia, _k_means._mini_batch_update_csr(X, x_squared_norms, centers, counts, nearest_center, old_center_buffer, compute_squared_diff)

    squared_diff = update_centers(X, centers, counts, nearest_center, compute_squared_diff, old_center_buffer)
    return inertia, squared_diff

def update_distances_for_reassignment(distances):
    distances -= distances.max()
    distances *= -1

def select_new_centers(distances, n_reassigns, random_state):
    rand_vals = random_state.rand(n_reassigns) * distances.sum()
    return np.searchsorted(distances.cumsum(), rand_vals)

def log_reassignment(n_reassigns, verbose):
    if verbose:
        print(f"[MiniBatchKMeans] Reassigning {n_reassigns} cluster centers.")

