    if sp.issparse(X) and not sp.issparse(centers):
        assign_rows_csr(X, new_centers, np.where(to_reassign)[0], centers)
    else:
        centers[to_reassign] = X[new_centers]

def update_centers(X, centers, counts, nearest_center, compute_squared_diff, old_center_buffer):
    k = centers.shape[0]
    squared_diff = 0.0
    for center_idx in range(k):
        center_mask = nearest_center == center_idx
        count = np.sum(center_mask)
        if count > 0:
            update_center(X, centers, counts, center_idx, center_mask, count, compute_squared_diff, old_center_buffer, squared_diff)
